import { tv } from "tailwind-variants";

const accordion = tv({
  slots: {
    root: "flex w-full flex-col",
    item: "flex w-full flex-col not-last:border-b not-last:border-border",
    header: "",
    trigger: [
      "group flex w-full items-start rounded-md py-1.5 text-start text-sm font-medium text-foreground transition-all duration-150 ease-default outline-none select-none",
      "hover:underline hover:underline-offset-4",
      "focus-visible:ring-2 focus-visible:ring-ring/50",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "[&_svg]:ms-auto [&_svg]:size-4 [&_svg]:shrink-0",
      "[&>svg]:mt-[calc((1lh-1rem)/2)] [&>svg]:transition-[rotate] [&>svg]:duration-300 [&>svg]:ease-default",
    ],
    panel: [
      "h-(--accordion-panel-height) overflow-hidden text-sm text-muted-foreground transition-[height] duration-300 ease-default",
      "data-disabled:opacity-50",
      "data-ending-style:h-0",
      "data-starting-style:h-0",
    ],
    panelContent: "pb-1.5",
  },
});

export { accordion };

"use client";

import { useDirection } from "@base-ui/react";
import { Accordion as BaseAccordion } from "@base-ui/react/accordion";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { accordion } from "./accordion.style";

function Accordion({ className, ...props }: BaseAccordion.Root.Props) {
  const direction = useDirection();

  return (
    <BaseAccordion.Root
      data-slot="accordion"
      className={mergeSlotClassName(accordion().root, className)}
      {...props}
      dir={direction}
    />
  );
}

function AccordionItem({ className, ...props }: BaseAccordion.Item.Props) {
  return (
    <BaseAccordion.Item
      data-slot="accordion-item"
      className={mergeSlotClassName(accordion().item, className)}
      {...props}
    />
  );
}

function AccordionHeader({ className, ...props }: BaseAccordion.Header.Props) {
  return (
    <BaseAccordion.Header
      data-slot="accordion-header"
      className={mergeSlotClassName(accordion().header, className)}
      {...props}
    />
  );
}

function AccordionTrigger({
  className,
  ...props
}: BaseAccordion.Trigger.Props) {
  return (
    <BaseAccordion.Trigger
      data-slot="accordion-trigger"
      className={mergeSlotClassName(accordion().trigger, className)}
      {...props}
    />
  );
}

function AccordionPanel({
  className,
  contentClassName,
  children,
  ...props
}: BaseAccordion.Panel.Props & { contentClassName?: string }) {
  return (
    <BaseAccordion.Panel
      data-slot="accordion-panel"
      className={mergeSlotClassName(accordion().panel, className)}
      {...props}
    >
      <div
        data-slot="accordion-panel-content"
        className={accordion().panelContent({ className: contentClassName })}
      >
        {children}
      </div>
    </BaseAccordion.Panel>
  );
}

export {
  Accordion,
  AccordionItem,
  AccordionHeader,
  AccordionTrigger,
  AccordionPanel,
};

export {
  Accordion,
  AccordionItem,
  AccordionHeader,
  AccordionTrigger,
  AccordionPanel,
} from "./accordion";
